279	+	for index := 0; index < len(runes); index++ {
280	+		switch runes[index] {
281	+		case '"', '\'', '`':
282	+			next, err := scanQuotedRunes(runes, index)
283	+			if err != nil {
284	+				return nil, err
285	+			}
286	+			index = next - 1
287	+		case '#':
288	+			next := index + 1
289	+			for next < len(runes) && runes[next] != '\n' {
290	+				next++
291	+			}
292	+			index = next - 1
293	+		case '(':
294	+			depthParen++
295	+		case ')':
296	+			depthParen--
297	+		case '[':
298	+			depthBracket++
299	+		case ']':
