99	// recoverFunc generic recover function
100	func recoverFunc(runInfo *runInfoStruct) {
101		recoverInterface := recover()
102		if recoverInterface == nil {
103			return
104		}
105		switch value := recoverInterface.(type) {
106		case *Error:
